import './gta-email-recovery-runtime.mjs';import fs from 'node:fs/promises';const{db}=await import('./reply-runtime-20261015.mjs');const dir='artifacts/partner-sales-audit-20261016/';const joined=JSON.parse(await fs.readFile(dir+'joined.json'));const contacts=JSON.parse(await fs.readFile(dir+'contacts.json'));const ids=[...new Set(joined.flatMap(x=>x.contacts.map(c=>c.id)))];for(const name of ['Candice Brennan','HARSHARN KAUR BRAR','Studio 92 Designs','MOREEN LYNCH','Nicole Miller'])for(const c of contacts.filter(c=>c.name===name))ids.push(c.id);
async function all(t,q={}){let a=[];for(let offset=0;;offset+=1000){const p=await db(t,{order:'id.asc',...q,limit:'1000',offset:String(offset)});a.push(...p);if(p.length<1000)return a;}}
const results=await Promise.allSettled([['history',async()=>{let a=[];for(let i=0;i<ids.length;i+=40)a.push(...await all('market_touches',{contact_id:'in.('+ids.slice(i,i+40).join(',')+')'}));return a;}],['quotes',()=>all('crm_quotes')],['emails',()=>all('crm_emails')]].map(async([k,fn])=>{const a=await fn();await fs.writeFile(dir+k+'.json',JSON.stringify(a));console.log(k,a.length)}));for(const r of results)if(r.status==='rejected')console.log(r.reason.message);
